import requests
from pathlib import Path
import zipfile

# Constants
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")

def task_func(url, filename):
    """
    Downloads a ZIP file from the given URL and extracts it.

    Args:
        url (str): URL of the ZIP file to download.
        filename (str): Name to use for the downloaded ZIP file.

    Returns:
        tuple: (status_message: str, extracted_files: list)
            - status_message contains "Error" when an exception occurs.
            - extracted_files is a list of filenames in the unzipped directory,
              or an empty list if extraction fails.
    """
    # Ensure directories exist
    try:
        DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
        ZIP_DIR.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        return (f"Error: Failed to create directories: {e}", [])

    zip_path = DOWNLOAD_DIR / filename

    # Download the file
    try:
        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()
        with open(zip_path, "wb") as f:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)
    except requests.RequestException as e:
        return (f"Error: Failed to download file from {url}: {e}", [])
    except OSError as e:
        return (f"Error: Failed to save downloaded file: {e}", [])

    # Extract the zip file
    extracted_files = []
    try:
        with zipfile.ZipFile(zip_path, "r") as zip_ref:
            zip_ref.extractall(ZIP_DIR)
            # Collect list of filenames in the unzipped directory (non-recursive)
            for item in ZIP_DIR.iterdir():
                if item.is_file():
                    extracted_files.append(item.name)
    except (zipfile.BadZipFile, zipfile.LargeZipFile) as e:
        return (f"Error: Invalid or unsupported ZIP file: {e}", [])
    except OSError as e:
        return (f"Error: File handling or extraction issue: {e}", [])

    return ("Success: File downloaded and extracted.", extracted_files)
